1	package com.loja.checkout.servico;
2	
3	import com.loja.checkout.dominio.Dinheiro;
4	import com.loja.checkout.dominio.Item;
5	import com.loja.checkout.dominio.clube.Nivel;
6	import com.loja.checkout.dominio.clube.Niveis;
7	import com.loja.checkout.dominio.cupom.Cupom;
8	import com.loja.checkout.dominio.cupom.Cupons;
9	import com.loja.checkout.dominio.entrega.Entrega;
10	import com.loja.checkout.dominio.entrega.Entregas;
11	import com.loja.checkout.dominio.pagamento.Pagamento;
12	import com.loja.checkout.dominio.pagamento.Pagamentos;
13	import com.loja.checkout.dominio.regiao.Regiao;
14	import com.loja.checkout.erro.ErroPedido;
15	import com.loja.checkout.web.ItemRequest;
16	import com.loja.checkout.web.ResumoRequest;
17	import com.loja.checkout.web.ResumoResponse;
18	import org.springframework.stereotype.Service;
19	
20	import java.math.BigDecimal;
21	import java.util.ArrayList;
22	import java.util.List;
23	
24	@Service
25	public class CalculadoraResumo {
26	
27	    public ResumoResponse calcular(ResumoRequest req) {
28	        List<Item> itens = validarItens(req.itens);
29	
30	        Nivel nivel = Niveis.buscar(req.nivelClube)
31	                .orElseThrow(() -> new ErroPedido("NIVEL_CLUBE_INVALIDO"));
32	
33	        Regiao regiao = Regiao.buscar(req.regiao)
34	                .orElseThrow(() -> new ErroPedido("REGIAO_INVALIDA"));
35	
36	        Entrega entrega = Entregas.buscar(req.modalidadeEntrega)
37	                .orElseThrow(() -> new ErroPedido("MODALIDADE_INVALIDA"));
38	
39	        BigDecimal pesoTotal = pesoTotal(itens);
40	        if (!entrega.disponivelPara(pesoTotal)) {
41	            throw new ErroPedido("MODALIDADE_INDISPONIVEL");
42	        }
43	
44	        BigDecimal subtotal = Dinheiro.arredondar(subtotal(itens));
45	        BigDecimal fretePadrao = Dinheiro.arredondar(entrega.frete(pesoTotal));
46	        BigDecimal frete = Dinheiro.arredondar(nivel.ajustarFrete(fretePadrao));
47	
48	        Cupom cupom = null;
49	        BigDecimal descontoCupom = Dinheiro.ZERO;
50	        if (req.cupom != null) {
51	            cupom = Cupons.buscar(req.cupom)
52	                    .orElseThrow(() -> new ErroPedido("CUPOM_INVALIDO"));
53	            if (!cupom.aplicavel(itens, subtotal)) {
54	                throw new ErroPedido("CUPOM_NAO_APLICAVEL");
55	            }
56	            descontoCupom = Dinheiro.arredondar(cupom.desconto(itens, subtotal, frete));
57	        }
58	
59	        BigDecimal seguro = Dinheiro.arredondar(subtotal.multiply(regiao.percentualSeguro()));
60	        BigDecimal totalPedido = Dinheiro.arredondar(
61	                subtotal.subtract(descontoCupom).add(frete).add(seguro));
62	
63	        Pagamento pagamento = Pagamentos.buscar(req.formaPagamento)
64	                .orElseThrow(() -> new ErroPedido("FORMA_PAGAMENTO_INVALIDA"));
65	
66	        int parcelas = req.parcelas == null ? 1 : req.parcelas;
67	        if (!pagamento.parcelasValidas(parcelas)) {
68	            throw new ErroPedido("PARCELAMENTO_INVALIDO");
69	        }
70	        if (!pagamento.disponivelPara(totalPedido)) {
71	            throw new ErroPedido("FORMA_PAGAMENTO_INDISPONIVEL");
72	        }
73	
74	        Pagamento.Ajuste ajuste = pagamento.calcular(totalPedido, parcelas);
75	
76	        ResumoResponse r = new ResumoResponse();
77	        r.subtotalProdutos = subtotal;
78	        r.descontoCupom = descontoCupom;
79	        r.frete = frete;
80	        r.prazoEntregaDias = entrega.prazoDias();
81	        r.seguro = seguro;
82	        r.ajustePagamento = ajuste.ajuste();
83	        r.totalFinal = ajuste.totalFinal();
84	        r.parcelas = parcelas;
85	        r.valorParcela = ajuste.valorParcela();
86	        r.creditoProximaCompra = Dinheiro.arredondar(nivel.credito(subtotal));
87	        r.brinde = nivel.brinde(subtotal);
88	        return r;
89	    }
90	
91	    private static List<Item> validarItens(List<ItemRequest> entrada) {
92	        if (entrada == null || entrada.isEmpty()) {
93	            throw new ErroPedido("PEDIDO_INVALIDO");
94	        }
95	        List<Item> itens = new ArrayList<>(entrada.size());
96	        for (ItemRequest i : entrada) {
97	            if (i == null
98	                    || i.precoUnitario == null || i.precoUnitario.signum() <= 0
99	                    || i.quantidade == null || i.quantidade <= 0
100	                    || i.pesoKg == null || i.pesoKg.signum() <= 0) {
101	                throw new ErroPedido("PEDIDO_INVALIDO");
102	            }
103	            itens.add(new Item(i.nome, i.precoUnitario, i.quantidade, i.pesoKg));
104	        }
105	        return itens;
106	    }
107	
108	    private static BigDecimal subtotal(List<Item> itens) {
109	        BigDecimal s = BigDecimal.ZERO;
110	        for (Item i : itens) s = s.add(i.total());
111	        return s;
112	    }
113	
114	    private static BigDecimal pesoTotal(List<Item> itens) {
115	        BigDecimal p = BigDecimal.ZERO;
116	        for (Item i : itens) p = p.add(i.pesoTotal());
117	        return p;
118	    }
119	}
