1	package com.loja.checkout.dominio.pagamento;
2	
3	import com.loja.checkout.dominio.Dinheiro;
4	
5	import java.math.BigDecimal;
6	import java.math.MathContext;
7	import java.math.RoundingMode;
8	
9	public class Cartao implements Pagamento {
10	    private static final BigDecimal TAXA = new BigDecimal("0.0199");
11	    private static final int SEM_JUROS_ATE = 3;
12	    private static final int MAX_PARCELAS = 12;
13	    private static final MathContext MC = MathContext.DECIMAL128;
14	
15	    @Override public String codigo() { return "CARTAO"; }
16	    @Override public boolean parcelasValidas(int parcelas) {
17	        return parcelas >= 1 && parcelas <= MAX_PARCELAS;
18	    }
19	    @Override public boolean disponivelPara(BigDecimal totalPedido) { return true; }
20	
21	    @Override public Ajuste calcular(BigDecimal totalPedido, int parcelas) {
22	        if (parcelas <= SEM_JUROS_ATE) {
23	            BigDecimal parcela = Dinheiro.arredondar(
24	                    totalPedido.divide(BigDecimal.valueOf(parcelas), MC));
25	            BigDecimal totalFinal = Dinheiro.arredondar(totalPedido);
26	            return new Ajuste(Dinheiro.ZERO, totalFinal, parcela);
27	        }
28	        BigDecimal um = BigDecimal.ONE;
29	        BigDecimal base = um.add(TAXA);
30	        BigDecimal baseElevado = base.pow(parcelas, MC);
31	        BigDecimal denominador = um.subtract(um.divide(baseElevado, MC));
32	        BigDecimal parcela = totalPedido.multiply(TAXA, MC).divide(denominador, MC);
33	        BigDecimal parcelaArred = parcela.setScale(2, RoundingMode.HALF_EVEN);
34	        BigDecimal totalFinal = Dinheiro.arredondar(
35	                parcelaArred.multiply(BigDecimal.valueOf(parcelas)));
36	        BigDecimal ajuste = Dinheiro.arredondar(totalFinal.subtract(totalPedido));
37	        return new Ajuste(ajuste, totalFinal, parcelaArred);
38	    }
39	}
