7	public class Pix implements Pagamento {
8	    private static final BigDecimal DESCONTO = new BigDecimal("0.05");
9	
10	    @Override public String codigo() { return "PIX"; }
11	    @Override public boolean parcelasValidas(int parcelas) { return parcelas == 1; }
12	    @Override public boolean disponivelPara(BigDecimal totalPedido) { return true; }
